import re, html, copy
X=open('unp/word/document.xml',encoding='utf-8').read()
PARAS=re.findall(r'<w:p[ >].*?</w:p>',X,flags=re.S)
def esc(s): return html.escape(s,quote=False)

def make_para(tpl, text):
    """Rebuild paragraph tpl with new text. **bold** supported; \n -> line break."""
    ppr=re.search(r'<w:pPr>.*?</w:pPr>',tpl,flags=re.S)
    ppr=ppr.group(0) if ppr else ''
    runs=re.findall(r'<w:r>(.*?)</w:r>',tpl,flags=re.S)
    base=None
    for r in runs:
        m=re.search(r'<w:rPr>.*?</w:rPr>',r,flags=re.S)
        if m and '<w:t' in r: base=m.group(0); break
    if base is None:
        base='<w:rPr><w:rFonts w:ascii="Calibri" w:cs="Calibri" w:eastAsia="Calibri" w:hAnsi="Calibri"/><w:sz w:val="21"/><w:szCs w:val="21"/><w:rtl w:val="0"/></w:rPr>'
    base=re.sub(r'<w:b w:val="1"/>|<w:bCs w:val="1"/>|<w:b/>|<w:bCs/>|<w:color w:val="0000ee"/>|<w:u w:val="single"/>','',base)
    bold=base.replace('<w:rPr>','<w:rPr>',1)
    bold=re.sub(r'(<w:rFonts[^>]*/>)',r'\1<w:b w:val="1"/><w:bCs w:val="1"/>',bold,count=1) if '<w:rFonts' in bold else bold.replace('<w:rPr>','<w:rPr><w:b w:val="1"/><w:bCs w:val="1"/>',1)
    out=[]
    for li,line in enumerate(text.split('\n')):
        if li>0: out.append('<w:r>'+base+'<w:br/></w:r>')
        parts=re.split(r'(\*\*.*?\*\*)',line)
        for p in parts:
            if not p: continue
            if p.startswith('**') and p.endswith('**'):
                out.append('<w:r>'+bold+'<w:t xml:space="preserve">'+esc(p[2:-2])+'</w:t></w:r>')
            else:
                out.append('<w:r>'+base+'<w:t xml:space="preserve">'+esc(p)+'</w:t></w:r>')
    head=re.match(r'<w:p[^>]*>',tpl).group(0)
    return head+ppr+''.join(out)+'</w:p>'

NEW={}   # index -> text or list of texts (list = expand/contract consecutive paragraphs of same style)
