# ---- tables: fill rows by cloning
def fill_table(Y, anchor_text, rows_data, header_rows):
    # find innermost <w:tbl> containing anchor_text (nesting-aware)
    tags=[(m.start(),m.group(0)) for m in re.finditer(r'<w:tbl>|</w:tbl>',Y)]
    best=None; stack=[]
    for pos,tag in tags:
        if tag=='<w:tbl>': stack.append(pos)
        else:
            st=stack.pop(); en=pos+len('</w:tbl>')
            if anchor_text in Y[st:en] and (best is None or en-st<best[1]-best[0]): best=(st,en)
    st,en=best; t=Y[st:en]
    assert t.count('<w:tbl>')==1, 'nested'
    rows=re.findall(r'<w:tr[ >].*?</w:tr>',t,flags=re.S)
    tpl_row=rows[header_rows]
    def fill_row(row,vals):
        cells=re.findall(r'<w:tc>.*?</w:tc>',row,flags=re.S)
        assert len(cells)==len(vals),(len(cells),len(vals))
        newrow=row
        for c,v in zip(cells,vals):
            ps=re.findall(r'<w:p[ >].*?</w:p>',c,flags=re.S)
            newc=c.replace(ps[0],make_para(ps[0],v),1)
            for extra in ps[1:]: newc=newc.replace(extra,'',1)
            newrow=newrow.replace(c,newc,1)
        return newrow
    new_rows=rows[:header_rows]+[fill_row(tpl_row,v) for v in rows_data]
    newt=t[:t.index(rows[0])]+''.join(new_rows)+'</w:tbl>'
    return Y[:st]+newt+Y[en:]
